package com.sibcraft.creeperborn;

import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.network.chat.Component;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.*;
import net.minecraft.tags.DamageTypeTags;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.effect.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.monster.Enemy;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;

/** Love and Sand share bounded input/effect infrastructure, not their combat mechanics. */
public final class PairPowers {
    private static final class State{Player owner;ServerLevel level;String fruit;int held=-1,direction;long press,heartbeat,recent=-1000;Vec3 last;Display.BlockDisplay charge;}
    private static final class Shot{Player owner;ServerLevel level;String fruit;Vec3 at,direction;float damage,stone;double remaining;long ends;int kind;Set<UUID> hit=new HashSet<>();Display.BlockDisplay visual;}
    private static final class Field{Player owner;ServerLevel level;Vec3 center,direction;int kind;double radius;long starts,ends;float damage;Display.BlockDisplay visual;}
    private static final class Stone{Player owner;LivingEntity target;ServerLevel level;float amount;long last,freeze,resist;boolean aiHeld,oldNoAi;Display.BlockDisplay visual;}
    private static final class Coffin{Player owner;LivingEntity target;ServerLevel level;long starts,ends,next;int pulses;float healed;boolean oldNoAi;Display.BlockDisplay visual;}
    private record Visual(Player owner,Display.BlockDisplay display,long ends){}
    private static final Map<UUID,State> states=new HashMap<>();
    private static final Map<UUID,Stone> stones=new HashMap<>();
    private static final Map<UUID,Coffin> coffins=new HashMap<>();
    private static final List<Shot> shots=new ArrayList<>();
    private static final List<Field> fields=new ArrayList<>();
    private static final Map<UUID,Visual> visuals=new HashMap<>();
    private static final Map<UUID,Long> landing=new HashMap<>();
    private static final Set<UUID> moving=new HashSet<>();
    private static long now(Entity e){return e.level().getGameTime();}
    public static boolean unlocked(Player p,String f){return (f.equals("love")||f.equals("sand"))&&p.entityTags().contains("cb_fruit_"+f)&&p.getUUID().equals(FruitClaims.owner(f));}
    public static boolean selected(Player p,String f){return unlocked(p,f)&&p.entityTags().contains("cb_mode_fruit")&&Dark.matches(p,f);}
    public static String current(Player p){return selected(p,"love")?"love":selected(p,"sand")?"sand":"";}
    public static int tier(Player p,String f){return unlocked(p,f)?Rubber.progressTier(Mastery.get(p,"cb_"+f+"_uses_"),Mastery.get(p,"cb_"+f+"_time_")):0;}
    public static void grant(Player p,String f,int tier){Mastery.set(p,"cb_"+f+"_uses_",tier==3?40:tier==2?10:0);Mastery.set(p,"cb_"+f+"_time_",tier==3?3600:tier==2?300:0);}
    public static boolean consume(Player p,ItemStack item,String f){if(item.isEmpty()||!Relics.kind(item).equals("fruit:"+f)||!FruitClaims.claimItem(p,item,f))return false;p.addTag("cb_fruit_"+f);grant(p,f,Relics.captureTier(item));p.addTag("cb_mode_fruit");if(Dark.unlocked(p))Dark.selectConsumed(p,f);item.shrink(1);return true;}
    private static int scale(Player p,String f,int a,int b,int c){return tier(p,f)>=3?c:tier(p,f)==2?b:a;}
    private static float bonus(Player p){return Mastery.harmony(p)?1.15f:1;}
    private static boolean usable(Player p,String f){return selected(p,f)&&available(p,f);}
    private static boolean available(Player p,String f){return unlocked(p,f)&&p.isAlive()&&!p.isRemoved()&&!p.isSpectator()&&!Dark.suppressed(p)&&!WaterRules.suppressed(p)&&!StringFruit.controlled(p)&&!rooted(p)&&!ClimatePowers.rooted(p);}
    private static boolean valid(Player p,ServerLevel level,String f){return available(p,f)&&p.level()==level;}
    private static long saved(Player p,String key){for(String t:p.entityTags())if(t.startsWith(key))try{return Long.parseLong(t.substring(key.length()));}catch(NumberFormatException ignored){}return 0;}
    private static void saved(Player p,String key,long value){for(String t:Set.copyOf(p.entityTags()))if(t.startsWith(key))p.removeTag(t);p.addTag(key+value);}
    private static State state(Player p,String f){State s=states.get(p.getUUID());if(s!=null&&(!s.fruit.equals(f)||s.level!=p.level())){forget(p);s=null;}if(s==null){s=new State();s.owner=p;s.level=(ServerLevel)p.level();s.fruit=f;states.put(p.getUUID(),s);}return s;}
    private static boolean enemy(Player p,LivingEntity e){return e!=p&&e.isAlive()&&!e.isSpectator()&&!p.isAlliedTo(e)&&!StringFruit.isKnight(e)&&(e instanceof Enemy||e instanceof Player);}
    private static boolean hit(Player p,LivingEntity e,float damage){return enemy(p,e)&&p.hasLineOfSight(e)&&ZoanPowers.poweredHit(p,e,ZoanPowers.activeFruit(p,"love","sand"),p.damageSources().playerAttack(p),damage*bonus(p));}
    private static Vec3 aim(Player p,double range){Vec3 a=p.getEyePosition(),b=a.add(p.getLookAngle().scale(range));var h=p.level().clip(new ClipContext(a,b,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,p));return h.getType()==HitResult.Type.MISS?b:h.getLocation();}
    private static LivingEntity target(Player p,double range){Vec3 a=p.getEyePosition(),b=aim(p,range);LivingEntity found=null;double nearest=range;for(var e:p.level().getEntitiesOfClass(LivingEntity.class,new AABB(a,b).inflate(.6))){if(!enemy(p,e))continue;var h=e.getBoundingBox().inflate(.4).clip(a,b);if(h.isPresent()&&a.distanceTo(h.get())<nearest){nearest=a.distanceTo(h.get());found=e;}}return found;}
    private static Vec3 flat(Player p){Vec3 v=p.getLookAngle().multiply(1,0,1).normalize();return v.lengthSqr()<.01?new Vec3(0,0,1):v;}
    private static void credit(Player p,String f){State s=state(p,f);if(now(p)-s.recent>=20)Mastery.set(p,"cb_"+f+"_uses_",Mastery.get(p,"cb_"+f+"_uses_")+1);s.recent=now(p);}
    public static void press(Player p,int move){press(p,move,0);}
    public static void press(Player p,int move,int direction){String f=current(p);if(f.isEmpty()||!usable(p,f)||move<0||move>2)return;State s=state(p,f);if(s.held>=0)return;s.held=move;s.direction=direction&15;s.press=now(p);s.heartbeat=now(p)+15;}
    public static void heartbeat(Player p){State s=states.get(p.getUUID());if(s!=null)s.heartbeat=now(p)+15;}
    public static void cancelInput(Player p){State s=states.get(p.getUUID());if(s!=null){s.held=-1;if(s.charge!=null)s.charge.discard();s.charge=null;}}
    public static void release(Player p,int move){State s=states.get(p.getUUID());if(s==null||s.held!=move)return;long held=now(p)-s.press;String f=s.fruit;int direction=s.direction;cancelInput(p);Creeperborn.say(p,cast(p,f,move,held,direction));}
    public static String cast(Player p,String f,int move,long held){return cast(p,f,move,held,0);}
    public static String cast(Player p,String f,int move,long held,int direction){
        if(!usable(p,f)||move<0||move>2)return "Fruit powers unavailable.";boolean hold=held>=7;int slot=move*2+(hold?1:0);String key="cb_"+f+"_ready_"+slot+"_";
        if(!(f.equals("sand")&&move==2&&!hold)&&now(p)<saved(p,key))return "Fruit move recovering.";
        if(hold&&held<(f.equals("sand")&&move==1?40:20))return "Keep charging for "+(f.equals("sand")&&move==1?"two seconds.":"one second.");
        if(p.getFoodData().getFoodLevel()<=6)return "Eat before using your fruit.";
        String result;int cooldown;boolean love=f.equals("love");ServerLevel level=(ServerLevel)p.level();
        if(love){
            if(move==0&&!hold){shoot(p,f,p.getLookAngle(),scale(p,f,4,6,8),scale(p,f,40,45,55),1,scale(p,f,20,28,36));result="Pistol Kiss!";cooldown=16;}
            else if(move==0){double range=scale(p,f,16,24,32);Vec3 from=p.getEyePosition(),end=aim(p,range),v=p.getLookAngle();for(var e:level.getEntitiesOfClass(LivingEntity.class,new AABB(from,end).inflate(4))){Vec3 offset=e.getBoundingBox().getCenter().subtract(from);double along=offset.dot(v);if(along>0&&along<=from.distanceTo(end)&&offset.subtract(v.scale(along)).length()<1.4+along/range*2&&hit(p,e,scale(p,f,8,10,14)))buildStone(p,e,scale(p,f,70,85,100));}for(int i=1;i<=6;i++)flash(p,from.lerp(end,i/6.0),v,2,2,12);result="Love-Love Beam!";cooldown=120;}
            else if(move==1&&!hold){double range=scale(p,f,3,4,5);for(var e:level.getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(range))){Vec3 delta=e.position().subtract(p.position());if(delta.length()<=range&&delta.normalize().dot(flat(p))>-.1&&hit(p,e,scale(p,f,6,8,10))){buildStone(p,e,scale(p,f,45,55,70));e.addEffect(new MobEffectInstance(MobEffects.SLOWNESS,20,2));flash(p,e.getBoundingBox().getCenter(),p.getLookAngle(),2,5,12);}}result="Perfume Femur!";cooldown=35;}
            else if(move==1){for(int i=-3;i<=3;i++){double a=i*.12;Vec3 v=p.getLookAngle();shoot(p,f,new Vec3(v.x*Math.cos(a)-v.z*Math.sin(a),v.y,v.x*Math.sin(a)+v.z*Math.cos(a)),scale(p,f,3,4,5),scale(p,f,25,30,40),1,scale(p,f,20,28,36));}result="Slave Arrow!";cooldown=160;}
            else if(!hold){if(!dash(p,scale(p,f,4,6,8),f,direction))return "Heart Step blocked.";result="Heart Step!";cooldown=40;}
            else{double radius=scale(p,f,6,9,12);int shattered=0;for(Stone stone:List.copyOf(stones.values()))if(stone.owner==p&&frozen(stone.target)&&stone.target.distanceToSqr(p)<=radius*radius&&p.hasLineOfSight(stone.target)){if(hit(p,stone.target,scale(p,f,10,15,22))){flash(p,stone.target.getBoundingBox().getCenter(),p.getLookAngle(),3,12,16);releaseStone(stone);shattered++;}}flash(p,p.position().add(0,1,0),new Vec3(0,1,0),(float)radius*2,5,16);result="Stone Breaker! "+shattered+" shattered";cooldown=180;}
        }else{
            if(move==0&&!hold){shoot(p,f,p.getLookAngle(),scale(p,f,4,5,7),0,6,scale(p,f,18,26,34));result="Desert Spada!";cooldown=20;}
            else if(move==0){Vec3 at=aim(p,scale(p,f,16,24,32));var h=level.clip(new ClipContext(at.add(0,6,0),at.add(0,-24,0),ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,p));if(h.getType()==HitResult.Type.MISS)return "Aim at ground for quicksand.";field(p,h.getLocation().add(0,.04,0),Vec3.ZERO,10,scale(p,f,3,5,7),100,0);result="Desert Girasole!";cooldown=180;}
            else if(move==1&&!hold){field(p,p.position().add(flat(p).scale(2)),flat(p).scale(scale(p,f,18,26,34)/40.0),7,scale(p,f,2,2,3),40,scale(p,f,2,3,4));result="Sables!";cooldown=100;}
            else if(move==1){field(p,p.position(),Vec3.ZERO,11,scale(p,f,4,6,8),scale(p,f,60,80,100),scale(p,f,1,2,3));result="Desert Storm!";cooldown=400;}
            else if(!hold){if(sandCharges(p)<=0)return "Sand Drift charges recovering.";if(!dash(p,scale(p,f,8,12,16),f,direction))return "Sand Drift blocked.";saved(p,"cb_sand_drift_n_",sandCharges(p)-1);result="Sand Drift! "+sandCharges(p)+" charges";cooldown=0;}
            else{LivingEntity e=target(p,scale(p,f,4,5,8));if(e==null)return "Aim at a nearby enemy for Sand Coffin.";if(ClimatePowers.rooted(e)||rooted(e)||Paw.airborne(e)||Tremor.airborne(e)||StringFruit.controlled(e))return "That target is already restrained.";Coffin c=new Coffin();c.owner=p;c.target=e;c.level=level;c.starts=now(p);c.ends=now(p)+(e instanceof Player?40:scale(p,f,40,60,80));c.next=now(p)+10;if(e instanceof Mob m){c.oldNoAi=m.isNoAi();m.setNoAi(true);}c.visual=display(p,e.position(),8,c.ends-now(p)+1);coffins.put(e.getUUID(),c);result="Sand Coffin — Desert Drain!";cooldown=240;}
        }
        saved(p,key,now(p)+Math.round(cooldown/bonus(p)));p.getFoodData().setFoodLevel(p.getFoodData().getFoodLevel()-(hold?2:1));credit(p,f);return result;
    }
    public static int sandCapacity(Player p){return scale(p,"sand",3,4,5);}
    public static int sandCharges(Player p){int cap=sandCapacity(p);long old=saved(p,"cb_sand_drift_cap_");int n=old==0?cap:(int)Math.max(0,Math.min(cap,saved(p,"cb_sand_drift_n_")+Math.max(0,cap-old)));long refill=old==0?now(p)+60:saved(p,"cb_sand_drift_at_");if(n>=cap){n=cap;refill=now(p)+60;}else if(now(p)>=refill){long add=1+(now(p)-refill)/60;n=(int)Math.min(cap,n+add);refill=n==cap?now(p)+60:refill+add*60;}saved(p,"cb_sand_drift_cap_",cap);saved(p,"cb_sand_drift_n_",n);saved(p,"cb_sand_drift_at_",refill);return n;}
    public static Vec3 dodgeDirection(float yaw,int keys){float forward=((keys&1)!=0?1:0)-((keys&2)!=0?1:0),right=((keys&8)!=0?1:0)-((keys&4)!=0?1:0);Vec3 v=StringFruit.controlDirection(yaw,forward,right);return v.lengthSqr()<.001?StringFruit.controlDirection(yaw,1,0):v.normalize();}
    private static boolean dash(Player p,double distance,String fruit,int keys){if(Paw.airborne(p)||Tremor.airborne(p))return false;Vec3 direction=dodgeDirection(p.getYRot(),keys),start=p.position(),end=start;ServerLevel level=(ServerLevel)p.level();for(double n=.25;n<=distance;n+=.25){Vec3 next=start.add(direction.scale(n));if(!level.hasChunkAt(BlockPos.containing(next))||!level.getWorldBorder().isWithinBounds(BlockPos.containing(next))||StringFruit.blocked(p,next)||!level.noCollision(p,p.getBoundingBox().move(next.subtract(start))))break;end=next;}if(end.distanceTo(start)<.5)return false;p.stopRiding();p.snapTo(end.x,end.y,end.z);if(p instanceof ServerPlayer sp)sp.teleportTo(level,end.x,end.y,end.z,Set.of(),p.getYRot(),p.getXRot(),false);p.resetFallDistance();landing.put(p.getUUID(),now(p)+100);for(int i=0;i<6;i++)flash(p,start.lerp(end,i/5.0).add(0,1,0),direction,1.4f,fruit.equals("love")?1:9,12);return true;}
    private static void shoot(Player p,String fruit,Vec3 direction,float damage,float stone,int kind,double range){Shot s=new Shot();s.owner=p;s.fruit=fruit;s.level=(ServerLevel)p.level();s.at=p.getEyePosition().add(direction.normalize().scale(.7));s.direction=direction.normalize();s.damage=damage;s.stone=stone;s.kind=kind;s.remaining=range;s.ends=now(p)+60;s.visual=display(p,s.at,kind,60);shots.add(s);}
    private static void field(Player p,Vec3 center,Vec3 direction,int kind,double radius,int ticks,float damage){Field f=new Field();f.owner=p;f.level=(ServerLevel)p.level();f.center=center;f.direction=direction;f.kind=kind;f.radius=radius;f.starts=now(p);f.ends=now(p)+ticks;f.damage=damage;f.visual=display(p,center,kind,ticks+1);fields.add(f);}
    public static float buildup(LivingEntity e){Stone s=stones.get(e.getUUID());return s==null?0:s.amount;}
    public static boolean frozen(LivingEntity e){Stone s=stones.get(e.getUUID());return s!=null&&s.freeze>now(e);}
    public static boolean rooted(LivingEntity e){return frozen(e)||coffins.containsKey(e.getUUID());}
    public static boolean locked(LivingEntity e){return rooted(e)&&!moving.contains(e.getUUID());}
    public static boolean immune(LivingEntity e,DamageSource source){return source.is(DamageTypeTags.IS_FALL)&&now(e)<landing.getOrDefault(e.getUUID(),0L);}
    private static void buildStone(Player owner,LivingEntity target,float amount){if(!enemy(owner,target)||ClimatePowers.rooted(target)||StringFruit.controlled(target)||coffins.containsKey(target.getUUID()))return;Stone s=stones.get(target.getUUID());if(s==null){s=new Stone();s.owner=owner;s.target=target;s.level=(ServerLevel)owner.level();stones.put(target.getUUID(),s);}if(now(target)<s.resist||s.freeze>now(target))return;s.amount=Math.min(100,s.amount+amount);s.last=now(owner);if(s.amount>=100){s.freeze=now(owner)+(target instanceof Player?scale(owner,"love",40,40,60):scale(owner,"love",60,80,160));s.resist=s.freeze+100;if(target instanceof Mob m){s.aiHeld=true;s.oldNoAi=m.isNoAi();m.setNoAi(true);}target.setDeltaMovement(Vec3.ZERO);if(s.visual!=null)s.visual.discard();s.visual=display(owner,target.position(),4,120);Creeperborn.say(owner,"Petrified! Hold C, then release Stone Breaker.");}else{target.addEffect(new MobEffectInstance(MobEffects.SLOWNESS,30,s.amount>=60?1:0));if(s.visual==null)s.visual=display(owner,target.position(),3,40);}if(target instanceof Player player)Creeperborn.say(player,s.amount>=100?"Petrified briefly!":"Petrification "+Math.round(s.amount)+"%");}
    private static void releaseStone(Stone s){if(s.aiHeld&&s.target instanceof Mob m)m.setNoAi(s.oldNoAi);s.aiHeld=false;landing.put(s.target.getUUID(),now(s.target)+40);s.freeze=0;s.amount=0;s.resist=Math.max(s.resist,now(s.target)+100);if(s.visual!=null)s.visual.discard();s.visual=null;s.target.setDeltaMovement(Vec3.ZERO);}
    private static void endCoffin(Coffin c,boolean finish){coffins.remove(c.target.getUUID());if(c.target instanceof Mob m)m.setNoAi(c.oldNoAi);if(c.visual!=null)c.visual.discard();c.target.setDeltaMovement(Vec3.ZERO);if(finish&&valid(c.owner,c.level,"sand")&&c.target.isAlive()){hit(c.owner,c.target,scale(c.owner,"sand",4,6,8));flash(c.owner,c.target.getBoundingBox().getCenter(),new Vec3(0,1,0),2,9,12);}}
    public static void tickPlayer(Player p){String fruit=current(p);State old=states.get(p.getUUID());if(old!=null&&(!available(p,old.fruit)||old.level!=p.level())){stopOwned(p);return;}if(fruit.isEmpty()){cancelInput(p);return;}if(!usable(p,fruit)){if(old!=null)stopOwned(p);return;}State s=state(p,fruit);if(s.held>=0&&now(p)>s.heartbeat)cancelInput(p);if(s.held>=0&&now(p)-s.press>=7){Vec3 at=p.getEyePosition().add(p.getLookAngle().scale(1.2));if(s.charge==null)s.charge=display(p,at,fruit.equals("love")?2:9,40);float size=.5f+Math.min(1,(now(p)-s.press)/20f);position(s.charge,at,p.getLookAngle(),size,size,size);touch(s.charge,p,40);if(now(p)%10==0)Creeperborn.say(p,fruit.equals("love")?"Heart charge — release to cast":"Gathering sand — release to cast");}if(now(p)%20==0){if(s.recent+200>now(p)||s.last!=null&&s.last.distanceToSqr(p.position())>.04)Mastery.set(p,"cb_"+fruit+"_time_",Mastery.get(p,"cb_"+fruit+"_time_")+1);s.last=p.position();}}
    private static void drive(LivingEntity e,Vec3 motion){if(ClimatePowers.rooted(e)||rooted(e)||Paw.airborne(e)||Tremor.airborne(e))return;ServerLevel level=(ServerLevel)e.level();Vec3 end=e.position().add(motion);if(!level.hasChunkAt(BlockPos.containing(end))||!level.getWorldBorder().isWithinBounds(BlockPos.containing(end))||StringFruit.blocked(e,end)||!level.noCollision(e,e.getBoundingBox().expandTowards(motion)))return;e.move(MoverType.SELF,motion);e.resetFallDistance();landing.put(e.getUUID(),now(e)+60);if(e instanceof ServerPlayer sp)sp.teleportTo(level,e.getX(),e.getY(),e.getZ(),Set.of(),e.getYRot(),e.getXRot(),false);}
    public static void tickEffects(){
        for(Shot s:List.copyOf(shots)){if(!valid(s.owner,s.level,s.fruit)||s.remaining<=0||now(s.owner)>=s.ends||s.visual==null||s.visual.isRemoved()){removeShot(s);continue;}Vec3 end=s.at.add(s.direction.scale(Math.min(1.3,s.remaining)));var wall=s.level.clip(new ClipContext(s.at,end,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,s.owner));boolean stop=wall.getType()!=HitResult.Type.MISS;if(stop)end=wall.getLocation();java.util.List<LivingEntity> contacts=new ArrayList<>();for(var e:s.level.getEntitiesOfClass(LivingEntity.class,new AABB(s.at,end).inflate(.5))){if(!enemy(s.owner,e)||s.hit.contains(e.getUUID()))continue;AABB box=e.getBoundingBox().inflate(.4);if(box.contains(s.at)||box.clip(s.at,end).isPresent())contacts.add(e);}contacts.sort(java.util.Comparator.comparingDouble(e->e.distanceToSqr(s.at)));for(var e:contacts){if(hit(s.owner,e,s.damage)&&s.stone>0)buildStone(s.owner,e,s.stone);s.hit.add(e.getUUID());flash(s.owner,e.getBoundingBox().getCenter(),s.direction,2,s.fruit.equals("love")?5:9,10);if(s.kind!=6){stop=true;break;}}if(stop){removeShot(s);continue;}s.remaining-=s.at.distanceTo(end);s.at=end;position(s.visual,end,s.direction,s.kind==6?2:1,s.kind==6?1.5f:1,1);touch(s.visual,s.owner,40);}
        for(Field f:List.copyOf(fields)){if(!valid(f.owner,f.level,"sand")||now(f.owner)>=f.ends||f.visual==null||f.visual.isRemoved()){if(f.visual!=null)f.visual.discard();fields.remove(f);continue;}if(f.kind==11)f.center=f.owner.position();else f.center=f.center.add(f.direction);if(!f.level.hasChunkAt(BlockPos.containing(f.center))){f.visual.discard();fields.remove(f);continue;}for(var e:f.level.getEntitiesOfClass(LivingEntity.class,new AABB(f.center,f.center).inflate(f.radius,f.kind==10?3:f.radius*2,f.radius))){Vec3 offset=e.position().subtract(f.center);if(!enemy(f.owner,e)||offset.multiply(1,0,1).length()>f.radius||!f.owner.hasLineOfSight(e))continue;if(f.kind==10){e.addEffect(new MobEffectInstance(MobEffects.SLOWNESS,12,2));Vec3 pull=f.center.subtract(e.position()).multiply(1,0,1);if(pull.length()>.6)drive(e,pull.normalize().scale(.13));}else if(f.kind==7){Vec3 pull=f.center.subtract(e.position()).multiply(1,0,1).scale(.16);if(pull.length()>.35)pull=pull.normalize().scale(.35);double lift=Math.max(-.08,Math.min(.08,f.center.y+1-e.getY()));drive(e,f.direction.add(pull).add(0,lift,0));}else e.addEffect(new MobEffectInstance(MobEffects.BLINDNESS,35,0));if(f.damage>0&&(now(f.owner)-f.starts)%20==0)hit(f.owner,e,f.damage);}position(f.visual,f.center,new Vec3(0,0,1),(float)f.radius*2,f.kind==10?.3f:(float)f.radius*2,(float)f.radius*2);touch(f.visual,f.owner,40);}
        for(Stone s:List.copyOf(stones.values())){if(!valid(s.owner,s.level,"love")||!s.target.isAlive()||s.target.isRemoved()||s.target.level()!=s.level){releaseStone(s);stones.remove(s.target.getUUID());continue;}if(s.freeze>0&&now(s.target)>=s.freeze)releaseStone(s);else if(s.freeze==0&&now(s.target)-s.last>30)s.amount=Math.max(0,s.amount-1);if(s.amount>0){if(s.visual!=null){position(s.visual,s.target.position(),new Vec3(0,0,1),s.target.getBbWidth()*3.4f,s.target.getBbHeight()*1.04f,s.target.getBbWidth()*3.4f);touch(s.visual,s.owner,40);}if(!frozen(s.target)&&now(s.target)%10==0)s.target.addEffect(new MobEffectInstance(MobEffects.SLOWNESS,15,s.amount>=60?1:0));}else if(s.visual!=null){s.visual.discard();s.visual=null;}if(s.amount==0&&now(s.target)>=s.resist)stones.remove(s.target.getUUID());}
        for(Coffin c:List.copyOf(coffins.values())){if(!valid(c.owner,c.level,"sand")||!c.target.isAlive()||c.target.isRemoved()||c.target.level()!=c.level||c.owner.distanceToSqr(c.target)>144){endCoffin(c,false);continue;}if(now(c.owner)>=c.ends){endCoffin(c,true);continue;}c.target.setDeltaMovement(Vec3.ZERO);if(now(c.owner)>=c.next){c.next+=Math.max(8,(c.ends-c.starts)/4);float before=c.target.getHealth();if(hit(c.owner,c.target,scale(c.owner,"sand",2,3,4))){float actual=Math.max(0,before-c.target.getHealth()),heal=Math.min(6-c.healed,actual*.5f);c.healed+=heal;c.owner.setHealth(Math.min(c.owner.getMaxHealth(),c.owner.getHealth()+heal));}c.pulses++;}float compress=1-.25f*Math.max(0,1-(c.ends-now(c.owner))/10f);position(c.visual,c.target.position(),new Vec3(0,0,1),c.target.getBbWidth()*2.4f*compress,c.target.getBbHeight()*1.2f,c.target.getBbWidth()*2.4f*compress);touch(c.visual,c.owner,40);}
        for(Visual v:List.copyOf(visuals.values()))if(v.display().isRemoved()||now(v.display())>=v.ends()){v.display().discard();visuals.remove(v.display().getUUID());}
    }
    private static void removeShot(Shot s){if(s.visual!=null)s.visual.discard();shots.remove(s);}
    private static Display.BlockDisplay display(Player p,Vec3 at,int kind,long ticks){ServerLevel level=(ServerLevel)p.level();var d=EntityTypes.BLOCK_DISPLAY.create(level,EntitySpawnReason.TRIGGERED);if(d==null)return null;d.addTag("cb_temporary_rock");d.setCustomName(Component.literal("cb_pair_"+kind));d.setCustomNameVisible(false);d.setBlockState(Blocks.STONE.defaultBlockState());var a=(com.sibcraft.creeperborn.mixin.PunchDisplayAccessor)d;a.creeperborn$duration(0);a.creeperborn$positionDuration(0);a.creeperborn$width(96);a.creeperborn$height(96);a.creeperborn$view(4);d.snapTo(at.x,at.y,at.z);if(!level.addFreshEntity(d))return null;visuals.put(d.getUUID(),new Visual(p,d,now(p)+ticks));return d;}
    private static void touch(Display.BlockDisplay d,Player p,int ticks){if(d!=null&&visuals.containsKey(d.getUUID()))visuals.put(d.getUUID(),new Visual(p,d,now(p)+ticks));}
    private static void position(Display.BlockDisplay d,Vec3 at,Vec3 facing,float x,float y,float z){if(d==null)return;d.snapTo(at.x,at.y,at.z);d.setTransformation(new com.mojang.math.Transformation(new org.joml.Vector3f(),Paw.orientation(facing),new org.joml.Vector3f(x,y,z),new org.joml.Quaternionf()));}
    private static void flash(Player p,Vec3 at,Vec3 facing,float size,int kind,int ticks){var d=display(p,at,kind,ticks);position(d,at,facing,size,size,size);}
    public static void tickVisual(Entity e){if(!(e.level() instanceof ServerLevel)||!(e instanceof Display.BlockDisplay)||e.getCustomName()==null||!e.getCustomName().getString().matches("cb_pair_([1-9]|1[0-2])"))return;Visual v=visuals.get(e.getUUID());if(v==null&&e.tickCount>2||v!=null&&now(e)>=v.ends()){e.discard();visuals.remove(e.getUUID());}}
    public static int visualCount(){return visuals.size();}public static int fieldCount(){return fields.size();}public static int coffinCount(){return coffins.size();}
    public static void tick(MinecraftServer server){for(var p:server.getPlayerList().getPlayers())if(!current(p).isEmpty()||states.containsKey(p.getUUID()))tickPlayer(p);tickEffects();landing.entrySet().removeIf(e->server.overworld().getGameTime()>=e.getValue());}
    /** Suppression/stun cancels outgoing effects without deleting incoming restraints. Selection only cancels uncast input. */
    public static void stopOwned(Player p){cancelInput(p);states.remove(p.getUUID());for(Shot s:List.copyOf(shots))if(s.owner==p)removeShot(s);for(Field f:List.copyOf(fields))if(f.owner==p){if(f.visual!=null)f.visual.discard();fields.remove(f);}for(Stone s:List.copyOf(stones.values()))if(s.owner==p){releaseStone(s);stones.remove(s.target.getUUID());}for(Coffin c:List.copyOf(coffins.values()))if(c.owner==p)endCoffin(c,false);for(Visual v:List.copyOf(visuals.values()))if(v.owner()==p){v.display().discard();visuals.remove(v.display().getUUID());}}
    /** Death/disconnect also releases any restraint on the departing player. */
    public static void forget(Player p){stopOwned(p);for(Stone s:List.copyOf(stones.values()))if(s.target==p){releaseStone(s);stones.remove(s.target.getUUID());}Coffin c=coffins.get(p.getUUID());if(c!=null)endCoffin(c,false);}

    public static void clear(){for(State s:List.copyOf(states.values()))forget(s.owner);for(Visual v:visuals.values())v.display().discard();states.clear();shots.clear();fields.clear();stones.clear();coffins.clear();visuals.clear();landing.clear();moving.clear();}
    public static String status(Player p,String fruit){return unlocked(p,fruit)?(fruit.equals("love")?"Love-Love":"Sand-Sand")+" tier "+tier(p,fruit)+"/3 | "+(fruit.equals("love")?"Z Kiss/Beam | X Kick/Arrows | C Heart Step/Stone Breaker":"Z Spada/Quicksand | X Sables/Storm | C Drift/Coffin Drain"):fruit+" locked";}
}
